            self._markers, self.default, self._string_encoder, self._indent,
            self._floatstr,
            self.key_separator, self.item_separator, self.sort_keys,
            self.skipkeys, _one_shot,
            _intstr=_int_to_decimal_text,
            _decimalstr=_decimal_to_json_number_text,
            _fractionstr=_fraction_to_fixed_array_text,
        )(o, 0)

