    # ------------------------------------------------------------------
    # 校验先于文本: 错误嵌套再深也不返回部分 JSON
    # ------------------------------------------------------------------
    def test_all_nested_inputs_validated_before_text(self):
        with self.assertRaises(ValueError):
            serialize_metrics(
                {"ok": 1, "bad": {"deep": [Decimal("NaN")]}}
            )
        with self.assertRaises(ValueError):
