                [Fraction(1, 2), {"x": Decimal("Infinity")}]
            )
        with self.assertRaises(TypeError):
            serialize_metrics(
                {"ok": Decimal("1"), "bad": {"deep": {1, 2}}}
            )
        with self.assertRaises(TypeError):
